const INDEX = /^(0|[1-9][0-9]*)$/;

export function resolvePointer(doc, pointer) {
  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
  if (pointer === '') return doc;
  if (pointer[0] !== '/') throw new SyntaxError('a pointer must be empty or start with /');

  let current = doc;
  for (const raw of pointer.slice(1).split('/')) {
    for (let i = 0; i < raw.length; i += 1) {
      if (raw[i] !== '~') continue;
      if (raw[i + 1] !== '0' && raw[i + 1] !== '1') {
        throw new SyntaxError('a ~ must be followed by 0 or 1');
      }
    }
    const token = raw.replace(/~1/g, '/').replace(/~0/g, '~');

    if (Array.isArray(current)) {
      if (!INDEX.test(token)) throw new SyntaxError(`${token} is not an array index`);
      const index = Number(token);
      if (index >= current.length) throw new ReferenceError(`${token} is past the end`);
      current = current[index];
      continue;
    }
    if (current === null || typeof current !== 'object') {
      throw new ReferenceError('a token cannot be applied to a value that is not a container');
    }
    if (!Object.prototype.hasOwnProperty.call(current, token)) {
      throw new ReferenceError(`the key ${token} is missing`);
    }
    current = current[token];
  }
  return current;
}
